import{_ as a,o as n,c as t,a5 as o}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Implementation plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/workspace-chat-collaboration/plan.md","filePath":"feature/workspace-chat-collaboration/plan.md"}'),s={name:"feature/workspace-chat-collaboration/plan.md"};function i(r,e,c,l,d,p){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="implementation-plan" tabindex="-1">Implementation plan <a class="header-anchor" href="#implementation-plan" aria-label="Permalink to &quot;Implementation plan&quot;">​</a></h1><ol><li>Preserve legacy general chat and route contracts. Introduce authenticated channel services, types and conversation selection under <code>src/pages/chat/</code>.</li><li>Split the UI into a sidebar, header/search controls, message timeline/actions, details panel and composer. Keep <code>index.tsx</code> as an orchestrator below 150 lines. Use current theme tokens and shared Button/Input/Sheet controls. Keep explicit opener references for controlled sheets, restore only a visible connected control, and avoid restoring navigation focus when a second sheet is opening.</li><li>Replace <code>useWorkspaceChat</code> with <code>useChatChannels</code>, <code>useChannelMessages</code> and <code>useChatRealtime</code>. Scope TanStack Query keys by account/workspace/channel/filters, cancel obsolete queries, deduplicate by sender and client ID, retry with original IDs, guard realtime parsing and explicitly acknowledge only visible messages.</li><li>Query server history for search/context/pinned/thread filters and retain cursor pagination. Apply the active context and root filters to optimistic/failed rows as well as canonical messages. Render load failures with retry. Key the workspace/conversation/composer by account, workspace, channel and context to isolate drafts; reconnect does not reset the composer.</li><li>Update both <code>src/i18n/locales/vi/chat.json</code> and <code>src/i18n/locales/en/chat.json</code>; preserve key parity.</li><li>Verify with the installed TypeScript, ESLint, production build and real-browser automation using isolated fixture accounts and intercepted HTTP/STOMP. No live messages are sent to other users during verification.</li></ol><h2 id="confirmed-backend-implementation" tabindex="-1">Confirmed backend implementation <a class="header-anchor" href="#confirmed-backend-implementation" aria-label="Permalink to &quot;Confirmed backend implementation&quot;">​</a></h2><p>Use Mongo <code>chat_channels</code> and <code>chat_channel_reads</code>, extend existing <code>chat_messages</code> with nullable channel/thread fields, pin and bounded reactions. Null channel identifies legacy general messages. Add an idempotent infrastructure migration for supporting compound indexes and partial channel-name uniqueness. Keep legacy queries strictly general. Add channel access/directory, channel administration, message query/write services and thin controllers. Reuse existing JWT authentication, membership/context validation and rate limiter. Guard new websocket topics inbound and outbound. Backend unit tests cover private isolation, cross-workspace roots, archive/posting rules, idempotency and atomic updates; add query filter regressions.</p><p>Frontend uses new authenticated services for persisted channels/messages and keeps <code>general</code> history available through the new facade. Compose channel/sidebar, form, settings/member management, thread panel, message actions, pinned view, search and mention picker. Server data is held in session-owned hooks, never localStorage.</p><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h2><p>Every path that reads a message must scope workspace and channel. Existing workspace member-list endpoints require management permissions; expose a dedicated minimal chat directory with membership checks. Deploy the infrastructure indexes before production use; migration does not run against shared databases automatically. Preserve uncertainty about unexecuted live multi-user tests.</p>',7)])])}const u=a(s,[["render",i]]);export{m as __pageData,u as default};
